let
    подключение = Excel.Workbook(File.Contents(pSource09), null, true),
    сырые_данные = подключение{[Item="Сырье_регионы",Kind="Table"]}[Data],
    меняем_типы = Table.TransformColumnTypes(сырые_данные,{{"Федеральный округ", type text}, {"Показатель", type text}, {"Регион", type text}, {"Дата", type date}, {"Значение", type number}, {"Код сырья", type text}}),
    пивот_таблицы = Table.Pivot(меняем_типы, List.Distinct(меняем_типы[Показатель]), "Показатель", "Значение"),
    первичный_ключ = Table.AddColumn(пивот_таблицы, "Ключ региона", each Text.Combine({[Регион], [#"Код сырья"], Date.ToText([Дата])}, "_"), type text),
    заполняем_пустоты = Table.ReplaceValue(первичный_ключ,null,0,Replacer.ReplaceValue,{"Импорт", "Валовый сбор", "Экспорт", "Потребление", "Потребление на переработку", "Потребление на кондитерский подсолнечник", "Потребление на семена", "Потери", "Приток/отток (РФ)", "Остатки на конец месяца", "Потребление на полножирную сою", "Потребление на производство жмыха", "Прочее потребление"}),
    выбираем_столбцы = Table.SelectColumns(заполняем_пустоты,{"Регион", "Дата", "Код сырья", "Импорт", "Валовый сбор", "Экспорт", "Потребление", "Потребление на переработку", "Потребление на кондитерский подсолнечник", "Потребление на семена", "Потери", "Потребление на полножирную сою", "Потребление на производство жмыха", "Прочее потребление", "Ключ региона"})
in
    выбираем_столбцы
